mapper.select:
select p.tenant_id from batch.archive_policy p
 where  and p.tenant_id > #{after}
 order by p.tenant_id limit #{limit}

mapper.sql:
h.tenant_id=#{candidate.tenantId}

    and h.event_key=#{candidate.eventKey}

        and h.aggregate_type='NOTIFICATION_DELIVERY'
        and h.aggregate_id in (
            select 'WEBHOOK:'||id from batch.webhook_delivery_log
             where tenant_id=#{candidate.tenantId} and terminal_event_key=#{candidate.eventKey}
            union all
            select 'RULE:'||id from batch.notification_delivery_log
             where tenant_id=#{candidate.tenantId} and terminal_event_key=#{candidate.eventKey}
            union all
            select 'PUSH:'||id from batch.console_push_job_delivery
             where tenant_id=#{candidate.tenantId} and terminal_event_key=#{candidate.eventKey})

    and h.terminal_event_key=#{candidate.eventKey}
